import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();

        int result = process(a, b, l, r);
        System.out.println(result);
        sc.close();
    }

    static int process(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b))
            return (a <= b) ? a + 1 : (2 * a - b);

        int[] pattern = new int[3 * (a + b) + 1];

        int last = 0;
        for (int i = 1; i <= a; i++) {
            pattern[i] = i;
            last = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            pattern[i] = last;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int count = 1;
            while (contains(pattern, count, a + b - a + 1, i - 1))
                count++;
            pattern[i] = count;
            last = count;
        }

        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            pattern[i] = last;
        }

        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            pattern[i] = pattern[i - (a + b)];
        }

        int[] countArr = new int[25];
        int startIdx = l % (a + b);
        if (startIdx == 0) startIdx += a + b;
        int endIdx = r - l + startIdx;
        if (endIdx < startIdx) endIdx += a + b;

        for (int i = startIdx; i <= endIdx; i++) {
            countArr[pattern[i]] = 1;
        }

        int totalCount = 0;
        for (int i = 1; i <= 24; i++) {
            totalCount += countArr[i];
        }
        return totalCount;
    }

    static boolean contains(int[] arr, int val, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (arr[i] == val)
                return true;
        }
        return false;
    }
}
